// Normalise the inbound payload and build text + image prompts.
const input = $input.first().json;
const b = (input.body !== undefined ? input.body : input) || {};

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const theme = String(b.theme || b.productName || '').trim();
const productName = String(b.productName || '').trim();
const description = String(b.description || '').trim();
const tone = String(b.tone || 'friendly and engaging').trim();
const destinationUrl = String(b.destinationUrl || '').trim();

let platforms = b.platforms || ['facebook'];
if (typeof platforms === 'string') {
  platforms = platforms.split(',').map((s) => s.trim()).filter(Boolean);
}
if (!Array.isArray(platforms) || platforms.length === 0) platforms = ['facebook'];

if (!theme) {
  throw new Error('Missing required field: provide "theme" or "productName".');
}

const subject = productName ? (productName + ' — ' + theme) : theme;

const systemPrompt = 'You are an expert social media marketing copywriter. Respond ONLY with a valid JSON object with exactly these keys: "caption" (string, 1-3 engaging sentences), "hashtags" (array of 5-10 short strings, no # symbol), "cta" (string, a short call to action). No markdown, no code fences, no extra keys.';
const userPrompt = 'Product/theme: ' + subject + '.' + (description ? (' Details: ' + description + '.') : '') + ' Tone: ' + tone + '. Write promotional social media copy.';

const imagePrompt = subject + ', professional product marketing photography, high quality, ' + tone + ' mood, soft studio lighting, vibrant colors, clean composition, promotional advertisement style';
const seed = Math.floor(Math.random() * 1000000);
const imageUrl = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(imagePrompt) + '?width=1024&height=1024&nologo=true&model=flux&seed=' + seed;

return [{
  json: {
    run_id: uuidv4(),
    theme,
    productName,
    description,
    tone,
    platforms,
    destinationUrl,
    subject,
    systemPrompt,
    userPrompt,
    imagePrompt,
    imageUrl,
    seed,
    groqModel: $env.GROQ_MODEL || 'llama-3.3-70b-versatile'
  }
}];

// Parse Groq's JSON content and merge with the prompt-builder data.
const groq = $input.first().json;
let content = '';
try { content = groq.choices[0].message.content || ''; } catch (e) { content = ''; }
content = String(content).trim().replace(/^```(?:json)?/i, '').replace(/```$/,'').trim();

let parsed;
try { parsed = JSON.parse(content); } catch (e) { parsed = { caption: content, hashtags: [], cta: '' }; }

const base = $('Build Prompts').first().json;

let tags = parsed.hashtags;
if (!Array.isArray(tags)) tags = String(tags || '').split(/[\s,]+/).filter(Boolean);
const hashtags = tags.map((h) => '#' + String(h).replace(/^#/, '').replace(/\s+/g, '')).filter((h) => h.length > 1).join(' ');

const caption = String(parsed.caption || '').trim();
const cta = String(parsed.cta || '').trim();
const fullMessage = [caption, cta, hashtags].filter(Boolean).join('\n\n');

return [{ json: { ...base, caption, hashtags, cta, fullMessage } }];

// Flatten a success row for post_logs.
const p = $('Parse Copy').first().json;
const fb = $input.first().json || {};
const reqEcho = { theme: p.theme, productName: p.productName, description: p.description, tone: p.tone, platforms: p.platforms, destinationUrl: p.destinationUrl };
return [{ json: {
  run_id: p.run_id,
  platform: 'facebook',
  status: 'success',
  post_id: fb.post_id || fb.id || null,
  error_message: null,
  theme: p.theme,
  product_name: p.productName || null,
  tone: p.tone,
  caption: p.caption,
  hashtags: p.hashtags,
  cta: p.cta,
  image_url: p.imageUrl,
  destination_url: p.destinationUrl || null,
  raw_request: JSON.stringify(reqEcho),
  raw_response: JSON.stringify(fb)
}}];

// Flatten a failure row for post_logs.
const p = $('Parse Copy').first().json;
const item = $input.first().json || {};
const err = item.error || item;
let msg;
if (err && (err.message || err.description)) { msg = err.message || err.description; }
else { try { msg = JSON.stringify(err).slice(0, 500); } catch (e) { msg = String(err).slice(0, 500); } }
const reqEcho = { theme: p.theme, productName: p.productName, description: p.description, tone: p.tone, platforms: p.platforms, destinationUrl: p.destinationUrl };
return [{ json: {
  run_id: p.run_id,
  platform: 'facebook',
  status: 'fail',
  post_id: null,
  error_message: msg,
  theme: p.theme,
  product_name: p.productName || null,
  tone: p.tone,
  caption: p.caption,
  hashtags: p.hashtags,
  cta: p.cta,
  image_url: p.imageUrl,
  destination_url: p.destinationUrl || null,
  raw_request: JSON.stringify(reqEcho),
  raw_response: JSON.stringify(item)
}}];
